"""
    Finds all simulations in the list given.

    :param flist:
    :param sim:
    :return: [list]
    """
def find_all_simulations(flist: Any, sim: Any) -> object {
    if not flist {
        return None;
    } else {
        matches = [];
        for fs in flist {
            if fs.startswith(sim) {
                matches.append(fs);
            }
        }
        return matches;
    }
}

